8	<style>
9	  :root { --gold:#c8a96e; --dark:#0a0a0a; --dark2:#141414; --line:rgba(200,169,110,.3); }
10	  * { margin:0; padding:0; box-sizing:border-box; }
11	  body { font-family:'Noto Sans TC', sans-serif; background:var(--dark); color:#fff; padding:36px 20px 100px; }
12	  .wrap { max-width:1500px; margin:0 auto; column-count:2; column-gap:48px; }
13	  .section-block { break-inside:avoid; -webkit-column-break-inside:avoid; display:inline-block; width:100%; }
14	  @media (max-width:900px){
15	    .wrap { column-count:1; }
16	  }
17	  h1 { font-size:30px; font-weight:900; margin-bottom:6px; }
18	  h1 span { color:var(--gold); }
19	  .sub { color:rgba(255,255,255,.5); font-size:16px; margin-bottom:18px; }
20	  .toolbar { display:flex; gap:12px; align-items:center; margin-bottom:28px; flex-wrap:wrap; }
21	  .btn-copy {
22	    background:rgba(200,169,110,.12); border:1px solid var(--gold); color:var(--gold);
23	    font-family:inherit; font-size:14px; font-weight:900; padding:10px 18px; border-radius:10px;
24	    cursor:pointer; transition:.2s;
25	  }
26	  .btn-copy:hover { background:rgba(200,169,110,.25); }
27	  .toast {
28	    position:fixed; bottom:28px; left:50%; transform:translateX(-50%) translateY(20px);
29	    background:var(--gold); color:#151107; font-weight:900; font-size:15px;
30	    padding:14px 28px; border-radius:12px; opacity:0; pointer-events:none;
31	    transition:.25s; z-index:999; box-shadow:0 8px 24px rgba(0,0,0,.4);
32	  }
33	  .toast.show { opacity:1; transform:translateX(-50%) translateY(0); }
34	  .section-title {
35	    display:flex; align-items:center; gap:12px; margin:40px 0 16px;
36	    font-size:20px; font-weight:900; color:var(--gold);
37	  }
38	  .section-title .count { font-size:14px; color:rgba(255,255,255,.4); font-weight:700; }
39	  .section-title::after { content:''; flex:1; height:1px; background:var(--line); }
40	  .grid { display:flex; flex-direction:column; gap:8px; }
41	  .item {
42	    display:flex; align-items:center; gap:12px; color:#fff;
43	    background:var(--dark2); border:1px solid var(--line); border-radius:10px;
44	    padding:10px 14px 10px 8px; transition:border-color .2s, background .2s;
45	  }
46	  .item:hover { border-color:var(--gold); background:#1a1a1a; }
47	  .item.dragging { opacity:.35; border-style:dashed; }
48	  .drag-handle {
49	    flex-shrink:0; width:28px; height:34px; display:flex; align-items:center; justify-content:center;
50	    color:rgba(255,255,255,.3); cursor:grab; font-size:18px; letter-spacing:-2px; touch-action:none;
51	    border-radius:6px; transition:.2s;
52	  }
53	  .drag-handle:hover { color:var(--gold); background:rgba(200,169,110,.1); }
54	  .drag-handle:active { cursor:grabbing; }
55	  .num {
56	    flex-shrink:0; width:34px; height:34px; border-radius:8px; background:#1c1c1c;
57	    display:flex; align-items:center; justify-content:center; font-weight:900;
58	    font-size:15px; color:var(--gold); border:1px solid var(--line);
59	  }
60	  .name { font-weight:700; font-size:17px; flex:1; color:#fff; text-decoration:none; }
61	  .name:hover { text-decoration:underline; }
62	  .url { font-size:13px; color:rgba(255,255,255,.35); font-variant-numeric:tabular-nums; }
63	  .badge {
64	    font-size:12px; font-weight:900; padding:3px 9px; border-radius:999px; flex-shrink:0;
65	  }
66	  .badge.public { background:rgba(6,199,85,.15); color:#06C755; }
67	  .badge.reserved { background:rgba(200,169,110,.15); color:var(--gold); }
68	  .badge.private { background:rgba(255,255,255,.08); color:rgba(255,255,255,.5); }
