566	  function getDragAfterElement(grid, y){
567	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
568	    return els.reduce(function(closest, child){
569	      var box = child.getBoundingClientRect();
570	      var offset = y - box.top - box.height / 2;
571	      if (offset < 0 && offset > closest.offset) {
572	        return { offset: offset, element: child };
573	      }
574	      return closest;
575	    }, { offset: -Infinity, element: null }).element;
576	  }
