642	    var sel = document.getElementById('bulkTargetSelect');
643	    sel.innerHTML = '';
644	    document.querySelectorAll('.section-title').forEach(function(title){
645	      var opt = document.createElement('option');
646	      opt.value = title.dataset.section;
647	      opt.textContent = title.querySelector('.title-text').textContent.trim();
648	      sel.appendChild(opt);
649	    });
