652	  document.getElementById('btnBulkMode').addEventListener('click', function(){
653	    bulkModeOn = !bulkModeOn;
654	    document.querySelector('.wrap').classList.toggle('bulk-mode', bulkModeOn);
655	    this.textContent = bulkModeOn ? '✅ 結束批量搬移' : '☑️ 批量搬移模式';
656	    if (bulkModeOn) {
657	      populateBulkSelect();
658	    } else {
659	      document.querySelectorAll('.bulk-checkbox:checked').forEach(function(cb){ cb.checked = false; });
660	      document.querySelectorAll('.item.selected').forEach(function(it){ it.classList.remove('selected'); });
