668	    if (!targetGrid) return;
669	    var checkedBoxes = Array.prototype.slice.call(document.querySelectorAll('.bulk-checkbox:checked'));
670	    if (checkedBoxes.length === 0) { toast('請先勾選要搬移的項目'); return; }
671	    var seenSections = {};
672	    var sourceGrids = [];
673	    checkedBoxes.forEach(function(cb){
674	      var item = cb.closest('.item');
675	      var srcGrid = item.closest('.grid');
676	      if (!seenSections[srcGrid.dataset.section]) {
677	        seenSections[srcGrid.dataset.section] = true;
678	        sourceGrids.push(srcGrid);
679	      }
680	      targetGrid.appendChild(item);
681	      cb.checked = false;
682	      item.classList.remove('selected');
683	    });
684	    sourceGrids.forEach(renumber);
685	    renumber(targetGrid);
