items.forEach(function(it){
  var n = it.querySelector('.name');
  if (n && n.textContent.trim() === '謝扉榆創業講座') target = it;
});
if (!target) { 'not found'; } else {
  target.querySelector('.item-del').click();
  'clicked, current grid: ' + target.closest('.grid').dataset.section;
}

